-- Classic 1.60 (WoW Forever): расстановка существ и объектов (creature, gameobject)
-- Источник: снифы официального сервера Classic (бета «актуал»), сборки 70245, 70291, 70338, 70425; сгенерировано ForeverSniffTools.
-- Правила: данные новых сущностей Forever (entry >= 250000) заменяются, для старых только добавляется недостающее.
-- Повторный запуск безопасен. 

-- creature: 430 новых спавнов (guid от 21500000); совпавшие с БД не включены
DELETE FROM `creature` WHERE `guid` BETWEEN 21500000 AND 22499999;

-- creature_addon: стойка, эмоция, ездовое существа и маршруты патрулей (PathId = guid * 10)
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 21500000 AND 22499999;
DELETE FROM `waypoint_path_node` WHERE `PathId` BETWEEN 215000000 AND 224999990;
DELETE FROM `waypoint_path` WHERE `PathId` BETWEEN 215000000 AND 224999990;

-- gameobject: 756 новых спавнов (guid от 21500000)
DELETE FROM `gameobject` WHERE `guid` BETWEEN 21500000 AND 22499999;
